import{_ as e,c as l,o,a3 as a}from"./chunks/framework.MI-M1z4O.js";const h=JSON.parse('{"title":"엔지니어링 작업 일지 및 포스트모텀 (Logs)","description":"SyncSeries 제품군 개발, 배포, 운영 과정에서 발생한 기술적 난제, 장애 원인 분석(RCA), 메모리 튜닝 및 성능 최적화 실무 기록 아카이브입니다.","frontmatter":{"title":"엔지니어링 작업 일지 및 포스트모텀 (Logs)","description":"SyncSeries 제품군 개발, 배포, 운영 과정에서 발생한 기술적 난제, 장애 원인 분석(RCA), 메모리 튜닝 및 성능 최적화 실무 기록 아카이브입니다.","head":[["meta",{"name":"keywords","content":"작업로그, 포스트모텀, Post-Mortem, 트러블슈팅, 메모리 누수, Electron, Playwright, Redis 분산락, MyBatis-Plus, 코드사이닝, 엠파시"}],["meta",{"property":"og:title","content":"엔지니어링 작업 일지 및 포스트모텀 | 엠파시(Empasy)"}],["meta",{"property":"og:description","content":"실제 프로덕션 장애 분석 및 엔지니어링 문제 해결 과정을 가감 없이 기록한 기술 일지입니다."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/logs/"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/logs/"}]],"sort":1},"headers":[],"relativePath":"logs/index.md","filePath":"ko/logs/index.md","lastUpdated":1795045877000}'),n={name:"logs/index.md"};function s(d,t,r,i,c,g){return o(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="엔지니어링-작업-일지-및-포스트모텀-logs" tabindex="-1">엔지니어링 작업 일지 및 포스트모텀 (Logs) <a class="header-anchor" href="#엔지니어링-작업-일지-및-포스트모텀-logs" aria-label="Permalink to “엔지니어링 작업 일지 및 포스트모텀 (Logs)”">​</a></h1><p>본 공간은 엠파시 엔지니어링 팀이 실제 프로덕션 환경 및 릴리즈 빌드 과정에서 마주한 <strong>기술적 장애, 메모리 누수, 동시성 병목, 빌드 서명 오류</strong>의 근본 원인(Root Cause)을 추적하고 해결한 실무 엔지니어링 일지입니다.</p><p>단순한 작업 일람을 넘어, <strong>재현 환경 -&gt; 근본 원인 분석(RCA) -&gt; 해결책 검증 -&gt; 재발 방지 대책</strong>의 표준 포스트모텀(Post-Mortem) 양식으로 체계화되어 있습니다.</p><hr><h2 id="작업-일지-및-포스트모텀-목록" tabindex="-1">작업 일지 및 포스트모텀 목록 <a class="header-anchor" href="#작업-일지-및-포스트모텀-목록" aria-label="Permalink to “작업 일지 및 포스트모텀 목록”">​</a></h2><h3 id="_1-synceta-데스크톱-앱-qa-엔진" tabindex="-1">1. SyncEta (데스크톱 앱 &amp; QA 엔진) <a class="header-anchor" href="#_1-synceta-데스크톱-앱-qa-엔진" aria-label="Permalink to “1. SyncEta (데스크톱 앱 &amp; QA 엔진)”">​</a></h3><ul><li><strong><a href="./20260210_electron_webview_memory_leak">2026-02-10: Electron 멀티 웹뷰 DOM 스냅샷 메모리 누수 분석 및 해결</a></strong>: 50개 이상 연속 시나리오 녹화 시 렌더러 프로세스 V8 힙 고갈 원인 규명 및 메모리 해제 최적화.</li><li><strong><a href="./20260218_playwright_dynamic_timeout_stabilization">2026-02-18: 지연 로딩 컴포넌트 대상 Playwright 액션 타임아웃 안정화</a></strong>: 무한 스크롤 및 지연 마운트 환경에서의 가상 스크롤 앵커 대기 메커니즘 개선.</li><li><strong><a href="./20260310_desktop_codesign_notarization_pipeline">2026-03-10: Windows Authenticode 서명 및 Apple Notarization 무인 배포 구축</a></strong>: GitHub Actions 러너 기반의 EV 인증서 코드 사이닝 및 macOS 게이트키퍼 통과 파이프라인.</li><li><strong><a href="./20250827_debugCrash">2025-08-27: 데스크톱 디버그 크래시 분석</a></strong>: Linux inotify 파일 워처 한도 초과(<code>ENOSPC: System limit for number of file watchers reached</code>) 트러블슈팅.</li><li><strong><a href="./20250827_electronDebug">2025-08-27: Electron 개발 환경 디버깅 일지</a></strong>: IntelliJ Electron 메인 프로세스 원격 디버거(<code>ws://127.0.0.1:5858</code>) 연결 및 브레이크포인트 설정 가이드.</li></ul><h3 id="_2-syncverse-syncboot-관제탑-msa-백엔드" tabindex="-1">2. SyncVerse &amp; SyncBoot (관제탑 &amp; MSA 백엔드) <a class="header-anchor" href="#_2-syncverse-syncboot-관제탑-msa-백엔드" aria-label="Permalink to “2. SyncVerse &amp; SyncBoot (관제탑 &amp; MSA 백엔드)”">​</a></h3><ul><li><strong><a href="./20260225_redis_redlock_sse_saga_orchestration">2026-02-25: Redis Redlock 및 SSE 기반 멀티 에이전트 트랜잭션 동기화 장애 복구</a></strong>: 네트워크 파티션 발생 시 분산 락 타임아웃 갱신 실패 및 Saga 롤백 동기화 이슈 해결.</li><li><strong><a href="./20260302_mybatis_metaobject_tenant_context_fix">2026-03-02: 멀티테넌시 환경 MyBatis-Plus 비동기 스레드 테넌트 ID 유실 버그 픽스</a></strong>: <code>ThreadLocal</code> 기반 테넌트 컨텍스트가 가상 스레드 풀에서 전파되지 않는 문제에 대한 <code>ScopedValue</code> 대체 픽스.</li></ul><hr><h2 id="엔지니어링-포스트모텀-작성-원칙" tabindex="-1">엔지니어링 포스트모텀 작성 원칙 <a class="header-anchor" href="#엔지니어링-포스트모텀-작성-원칙" aria-label="Permalink to “엔지니어링 포스트모텀 작성 원칙”">​</a></h2><ol><li><strong>비난 없는 사후 검토 (Blameless Post-Mortem)</strong>: 시스템 구조와 프로세스 취약점에 집중하여 실패를 조직적 자산으로 전환합니다.</li><li><strong>정확한 메트릭 기반 기록</strong>: 장애 발생 시점(T0), 인지 시점(T1), 완화 시점(T2), 완전 해결 시점(T3)의 타임라인을 명시합니다.</li><li><strong>코드 레벨 변경점 명시</strong>: 패치 전/후의 소스 코드 Diff를 포함하여 후속 엔지니어가 즉시 참조할 수 있도록 합니다.</li></ol><hr><h2 id="장애-등급-및-대응-타임라인-요약-매트릭스" tabindex="-1">장애 등급 및 대응 타임라인 요약 매트릭스 <a class="header-anchor" href="#장애-등급-및-대응-타임라인-요약-매트릭스" aria-label="Permalink to “장애 등급 및 대응 타임라인 요약 매트릭스”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">일지 ID</th><th style="text-align:left;">대상 제품</th><th style="text-align:left;">핵심 기술 영역</th><th style="text-align:left;">해결 전 증상</th><th style="text-align:left;">해결 후 정량 개선 지표</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>20260210</code></strong></td><td style="text-align:left;"><code>SyncETA</code></td><td style="text-align:left;">Electron Webview / V8 Heap</td><td style="text-align:left;">50회 연속 녹화 시 렌더러 OOM 크래시</td><td style="text-align:left;">메모리 점유량 <strong>68% 감소</strong>, 500회 연속 녹화 무장애</td></tr><tr><td style="text-align:left;"><strong><code>20260218</code></strong></td><td style="text-align:left;"><code>SyncETA</code></td><td style="text-align:left;">Playwright / Virtual Scroll</td><td style="text-align:left;">지연 마운트 그리드에서 간헐적 Timeout</td><td style="text-align:left;">동적 타임아웃 안정화로 Flaky 실패율 <strong>0.2% 미만</strong> 달성</td></tr><tr><td style="text-align:left;"><strong><code>20260225</code></strong></td><td style="text-align:left;"><code>SyncVerse</code></td><td style="text-align:left;">Redis Redlock / SSE Saga</td><td style="text-align:left;">네트워크 순단 시 분산 락 갱신 누락</td><td style="text-align:left;">Watchdog 자동 연장 및 보상 롤백 정합성 <strong>100% 보장</strong></td></tr><tr><td style="text-align:left;"><strong><code>20260302</code></strong></td><td style="text-align:left;"><code>SyncBoot</code></td><td style="text-align:left;">Java 25 Virtual Threads</td><td style="text-align:left;">비동기 작업 시 <code>ThreadLocal</code> 테넌트 유실</td><td style="text-align:left;"><code>ScopedValue</code> 전환으로 멀티테넌트 격리 누수 <strong>0건</strong></td></tr><tr><td style="text-align:left;"><strong><code>20260310</code></strong></td><td style="text-align:left;"><code>SyncETA</code></td><td style="text-align:left;">Windows EV / macOS Notarization</td><td style="text-align:left;">수동 코드 서명으로 릴리즈 2시간 소요</td><td style="text-align:left;">GitHub Actions 무인 서명·공증 파이프라인 <strong>12분 이내 완결</strong></td></tr><tr><td style="text-align:left;"><strong><code>20250827-A</code></strong></td><td style="text-align:left;"><code>SyncETA</code></td><td style="text-align:left;">Linux <code>inotify</code> Watcher</td><td style="text-align:left;">개발 서버 구동 중 <code>ENOSPC</code> 프로세스 종료</td><td style="text-align:left;"><code>fs.inotify.max_user_watches=524288</code> 영구 튜닝 표준화</td></tr><tr><td style="text-align:left;"><strong><code>20250827-B</code></strong></td><td style="text-align:left;"><code>SyncETA</code></td><td style="text-align:left;">IntelliJ / V8 Inspector</td><td style="text-align:left;">Electron 메인 프로세스 브레이크포인트 미작동</td><td style="text-align:left;"><code>ws://127.0.0.1:5858</code> 원격 디버거 소켓 직결 절차 수립</td></tr></tbody></table>',15)])])}const f=e(n,[["render",s]]);export{h as __pageData,f as default};
